# New Modern-tab polities for the 1920, 1938 and 1960 ticks.
# images: (Commons file or search query, caption, role)
P = []
def add(**k): P.append(k)

add(id="weimar-republic", name="Weimar Republic", type="republic", yearsActive="1918–1933", colorFrom="german-empire",
 summary="Germany's first parliamentary democracy, proclaimed after the 1918 revolution and governed under the Weimar constitution until Hitler's appointment as chancellor in 1933.",
 description="The German Reich became a republic in November 1918 when the Kaiser abdicated, and a national assembly meeting at Weimar adopted a democratic constitution in 1919. The Treaty of Versailles took Alsace-Lorraine, Posen and West Prussia, left East Prussia cut off by the Polish Corridor, and imposed reparations. The republic survived putsch attempts, the occupation of the Ruhr and the hyperinflation of 1923, then enjoyed a brief stabilisation under Gustav Stresemann before the Depression broke its party system and opened the way for the Nazis.",
 conflicts="The Spartacist rising (1919) and the Kapp Putsch (1920) came from left and right; Hitler's Munich Beer Hall Putsch failed in 1923. France and Belgium occupied the Ruhr in 1923 over unpaid reparations. Freikorps fought in the Baltic and in Upper Silesia against Polish insurgents.",
 leaders="Friedrich Ebert (SPD) was the first president (1919–1925), followed by Field Marshal Paul von Hindenburg. Gustav Stresemann, briefly chancellor and then foreign minister (1923–1929), negotiated Locarno and League membership. Heinrich Brüning governed by emergency decree from 1930.",
 religion="Protestant churches lost their status as state churches under the 1919 constitution, though they remained the majority faith. The Catholic Centre Party sat in almost every cabinet, and Germany's Jewish community, about 1% of the population, was highly visible in culture and the professions.",
 culture="Berlin became a capital of cabaret, cinema and nightlife. The Bauhaus, founded by Walter Gropius at Weimar in 1919, joined art, craft and industry. Radio and illustrated magazines created a mass culture for the first time.",
 literature="Thomas Mann published The Magic Mountain (1924); Alfred Döblin's Berlin Alexanderplatz (1929) and Erich Maria Remarque's All Quiet on the Western Front (1929) became bestsellers. Bertolt Brecht and Kurt Weill staged The Threepenny Opera in 1928.",
 art="Expressionist film (The Cabinet of Dr Caligari, 1920; Metropolis, 1927) and the New Objectivity painters Otto Dix and George Grosz satirised war profiteers and street life. The Bauhaus moved to Dessau in 1925 and set the look of modern design.",
 ideas="Max Weber lectured on politics as a vocation (1919); Carl Schmitt attacked liberal parliamentarism; the Frankfurt Institute for Social Research (1923) began critical theory. Martin Heidegger's Being and Time appeared in 1927.",
 science="Germany led world physics: Heisenberg's matrix mechanics (1925), Born's statistical interpretation and Einstein's work in Berlin. The Kaiser Wilhelm Society ran research institutes in chemistry and biology.",
 story=[{"title":"A wheelbarrow of marks","text":"In November 1923 one US dollar bought 4.2 trillion paper marks. Workers were paid twice a day and ran to spend their wages before prices rose again. The Rentenmark, backed by a mortgage on German land, ended the inflation almost overnight."}],
 sources="Encyclopaedia Britannica, 'Weimar Republic'; R. J. Evans, The Coming of the Third Reich (2003); E. D. Weitz, Weimar Germany: Promise and Tragedy (2007).",
 images=[("Bundesarchiv Bild 102-00104, Inflation, Tapezieren mit Geldscheinen.jpg","Wallpapering with banknotes during the 1923 hyperinflation","culture"),
         ("Bauhaus Dessau Hauptgebäude","The Bauhaus building in Dessau, by Walter Gropius (1925–26)","art")])

add(id="nazi-germany", name="Nazi Germany (Third Reich)", type="dictatorship", yearsActive="1933–1945", colorFrom="germany",
 summary="The National Socialist dictatorship that ruled Germany from 1933, annexed Austria and the Sudetenland in 1938, started the Second World War and carried out the Holocaust before its defeat in 1945.",
 description="Hitler became chancellor in January 1933 and within months the Reichstag fire decree and the Enabling Act had abolished civil liberties and parliamentary rule. Political parties and trade unions were banned, and the Nuremberg Laws of 1935 stripped Jews of citizenship. Rearmament, the remilitarisation of the Rhineland (1936), the Anschluss with Austria (March 1938) and the Munich Agreement over the Sudetenland (September 1938) overturned Versailles. Weeks later the Kristallnacht pogrom showed where the regime was heading.",
 conflicts="Germany intervened in the Spanish Civil War, where the Condor Legion bombed Guernica (1937). After annexing Austria and the Sudetenland in 1938 it occupied Prague in March 1939 and invaded Poland on 1 September 1939, starting the Second World War in Europe.",
 leaders="Adolf Hitler ruled as Führer from 1934. Hermann Göring ran the Four-Year Plan and the Luftwaffe, Joseph Goebbels propaganda, and Heinrich Himmler the SS and police. Hjalmar Schacht financed rearmament until 1937.",
 religion="The regime signed a concordat with the Vatican in 1933 but persecuted dissenting clergy; the Protestant Confessing Church resisted the Nazi-backed 'German Christians'. Jews were driven from public life, and about six million European Jews were murdered in the Holocaust.",
 culture="Party rallies at Nuremberg, the 1936 Berlin Olympics and Leni Riefenstahl's films staged a cult of the leader and the 'people's community'. Modern art was condemned in the 1937 'Degenerate Art' exhibition and many artists and scientists emigrated.",
 literature="Books by Jewish, pacifist and leftist authors were burned in May 1933. Thomas Mann, Brecht and many others wrote in exile, while officially approved literature celebrated soil, blood and war.",
 art="Albert Speer's monumental architecture and Arno Breker's sculpture defined the official style. The 'Degenerate Art' show in Munich mocked works by Kirchner, Nolde, Klee and others.",
 ideas="Nazi ideology combined racial antisemitism, Lebensraum (living space) in the east and the Führer principle. Philosophers such as Heidegger briefly lent it prestige, while Arendt, Adorno and others analysed it from exile.",
 science="Racial 'science' was put at the service of the state, and the expulsion of Jewish scholars cost Germany a large part of its physics and mathematics. Otto Hahn and Fritz Strassmann discovered nuclear fission in Berlin in December 1938.",
 story=[{"title":"The Anschluss","text":"On 12 March 1938 German troops crossed into Austria without a shot fired. Hitler spoke to cheering crowds in Vienna's Heldenplatz three days later, and a rigged plebiscite claimed 99.7% approval. Persecution of Vienna's Jews began within hours."}],
 sources="Encyclopaedia Britannica, 'Nazi Party'; R. J. Evans, The Third Reich in Power (2005); I. Kershaw, Hitler (1998–2000).",
 images=[("Bundesarchiv Bild 146-1972-028-14, Wien, Heldenplatz, Hitler-Rede.jpg","Crowds on Vienna's Heldenplatz as Hitler announces the Anschluss, March 1938","culture"),
         ("Bundesarchiv Bild 183-H13160, Beim Münchener Abkommen.jpg","Chamberlain, Daladier, Hitler, Mussolini and Ciano at the Munich Agreement, September 1938","leader")])

add(id="ukrainian-ssr", name="Ukrainian SSR", type="soviet republic", yearsActive="1919–1991 (founding member of the USSR in 1922)", colorFrom="ukraine",
 summary="The Soviet Ukrainian republic established by the Bolsheviks in 1919 after the defeat of the Ukrainian People's Republic, a founding member of the USSR in 1922.",
 description="Ukraine declared independence as the Ukrainian People's Republic in January 1918, but was fought over by Bolsheviks, Whites, Poles, anarchists and the Directorate of Symon Petliura. By 1920 the Red Army held most of the country and the Ukrainian Soviet Socialist Republic, with its capital at Kharkiv, was nominally a separate state allied to Soviet Russia. The 1921 Treaty of Riga left Galicia and western Volhynia to Poland. In the 1920s 'Ukrainisation' promoted the language, but collectivisation brought the famine of 1932–33 (the Holodomor), which killed millions.",
 conflicts="The Soviet–Ukrainian war and the Polish–Soviet war (1919–1921) were fought on its soil; Nestor Makhno's anarchist army controlled the south-east until 1921. Peasant risings against grain requisitioning continued after the civil war.",
 leaders="Christian Rakovsky headed the Soviet Ukrainian government (1919–1923). Mykola Skrypnyk led the Ukrainisation policy. Stanislav Kosior and later Nikita Khrushchev (from 1938) headed the Ukrainian Communist Party.",
 religion="The Orthodox Church was persecuted; the Ukrainian Autocephalous Orthodox Church formed in 1921 and was crushed in 1930. Greek Catholics lived mostly in Polish-held Galicia.",
 culture="The 1920s saw an explosion of Ukrainian-language theatre, film and publishing, including Les Kurbas's Berezil theatre and Oleksandr Dovzhenko's films. Most of this generation was shot or exiled in the 1930s, the 'Executed Renaissance'.",
 literature="Mykola Khvylovy called for Ukrainian literature to turn 'away from Moscow' toward Europe. Pavlo Tychyna and Mykola Zerov were among the leading poets.",
 art="Kazimir Malevich taught in Kyiv, and Oleksandr Bohomazov and Vadym Meller worked in a Ukrainian avant-garde style. Dovzhenko's film Earth (1930) is a classic of Soviet cinema.",
 ideas="'National communism' tried to combine Soviet socialism with Ukrainian national development until Stalin condemned it.",
 science="The All-Ukrainian Academy of Sciences, founded in Kyiv in 1918, survived the revolution; Kharkiv's Physical-Technical Institute became a centre of Soviet nuclear physics.",
 story=[{"title":"Kharkiv, capital","text":"The Soviets made Kharkiv, not Kyiv, the capital of their Ukraine from 1919 to 1934, because it was industrial, Russian-speaking and close to Russia. The Derzhprom building, one of the first Soviet skyscrapers, was built there as a seat of government."}],
 sources="Encyclopaedia Britannica, 'Ukraine: Soviet Ukraine'; S. Plokhy, The Gates of Europe (2015); O. Subtelny, Ukraine: A History (4th ed. 2009).",
 images=[("Derzhprom Kharkiv","Derzhprom, the government building in Kharkiv, capital of Soviet Ukraine (1925–28)","art")])

add(id="byelorussian-ssr", name="Byelorussian SSR", type="soviet republic", yearsActive="1919–1991 (founding member of the USSR in 1922)", colorFrom="belarus",
 summary="The Soviet Belarusian republic, proclaimed in 1919 and re-established in 1920 after the Polish–Soviet war, a founding member of the USSR whose western half was held by Poland until 1939.",
 description="A Belarusian People's Republic was declared under German occupation in March 1918, but the Bolsheviks proclaimed a Soviet Socialist Republic of Byelorussia in January 1919 and merged it briefly with Lithuania. The Polish–Soviet war swept across the country; in 1920 the republic was restored around Minsk, and the Treaty of Riga (1921) split Belarusian lands between Poland and the Soviets. The BSSR joined the USSR in 1922 and was enlarged eastward in 1924 and 1926.",
 conflicts="Minsk changed hands several times in 1919–1920 during the Polish–Soviet war. Stalin's purges in the 1930s, including the Kurapaty killings outside Minsk, devastated the republic's elite.",
 leaders="Alexander Chervyakov headed the Soviet Belarusian government through the 1920s. Belarusian national communists such as Usevalad Ignatouski led the cultural revival before the purges.",
 religion="Orthodox, Catholic and Jewish communities lived side by side; Minsk was nearly half Jewish. All faiths were persecuted under Soviet anti-religious campaigns, and Yiddish was one of the republic's four official languages in the 1920s.",
 culture="'Belarusisation' in the 1920s opened Belarusian-language schools, newspapers and the Belarusian State University (1921).",
 literature="The poets Yanka Kupala and Yakub Kolas, founders of modern Belarusian literature, remained in Soviet Belarus and were made academicians.",
 art="Marc Chagall's Vitebsk art school (1918–1922) brought Malevich and El Lissitzky to the city and briefly made it a centre of the avant-garde.",
 ideas="National communists argued that Soviet power could foster a Belarusian nation; by the 1930s this was branded 'bourgeois nationalism'.",
 science="The Institute of Belarusian Culture (1922) became the Belarusian Academy of Sciences in 1928.",
 story=[{"title":"Four official languages","text":"The 1927 constitution of Soviet Belarus gave equal status to Belarusian, Russian, Polish and Yiddish, and the state emblem carried the slogan 'Workers of the world, unite!' in all four."}],
 sources="Encyclopaedia Britannica, 'Belarus: History'; A. Wilson, Belarus: The Last European Dictatorship (2011); P. Rudling, The Rise and Fall of Belarusian Nationalism, 1906–1931 (2014).",
 images=[("Marc Chagall Vitebsk","Marc Chagall Museum in Vitebsk, where Chagall founded his People's Art School in 1918","art")])

add(id="south-russia", name="White South Russia (Wrangel's Crimea)", type="military government", yearsActive="1919–1920",
 colorFrom="russian-empire",
 summary="The anti-Bolshevik White government of South Russia, which by 1920 held only Crimea under General Pyotr Wrangel before its evacuation to Constantinople in November 1920.",
 description="The Armed Forces of South Russia under Anton Denikin advanced on Moscow in 1919 and reached Oryol before being driven back to the Black Sea. In April 1920 Denikin handed command to Pyotr Wrangel, who held Crimea, introduced a land reform and tried to win recognition from France. When the Red Army stormed the Perekop isthmus in November 1920, about 150,000 soldiers and civilians were evacuated by ship, a founding moment of the Russian emigration.",
 conflicts="Denikin's march on Moscow failed at Oryol in October 1919. Wrangel's army broke out into northern Tavria in summer 1920 while the Reds were fighting Poland, but the Red Army and Makhno's anarchists stormed Perekop on 7–11 November 1920.",
 leaders="Anton Denikin (1919–1920) and Baron Pyotr Wrangel (1920) commanded. Alexander Krivoshein, a pre-war minister, headed Wrangel's civil government.",
 religion="Russian Orthodox clergy supported the Whites; Metropolitan Anthony (Khrapovitsky) later founded the Russian Orthodox Church Outside Russia among the émigrés.",
 culture="Crimea filled with refugees from the old elite: officers, writers, aristocrats and Cossacks.",
 literature="Mikhail Bulgakov's play The Flight (Beg) and Ivan Shmelyov's The Sun of the Dead depict White Crimea and its fall.",
 art="White propaganda posters answered the Bolsheviks' poster campaigns.",
 ideas="The Whites stood for a 'Russia one and indivisible' but could not agree on monarchy, land or the national minorities.",
 science="Many scientists who left with the evacuation continued their work in Prague, Belgrade and Paris.",
 story=[{"title":"The evacuation","text":"Between 13 and 16 November 1920, 126 ships left Sevastopol, Yalta, Feodosia and Kerch carrying Wrangel's army and its families. Many soldiers spent the next year in camps at Gallipoli before scattering across Europe."}],
 sources="Encyclopaedia Britannica, 'Russian Civil War'; E. Mawdsley, The Russian Civil War (1987); W. B. Lincoln, Red Victory (1989).",
 images=[("Pyotr Wrangel","General Pyotr Wrangel, last commander of the White forces in South Russia","leader")])

add(id="armenia-republic", name="First Republic of Armenia", type="republic", yearsActive="1918–1920",
 summary="The independent Armenian state declared in May 1918, which fought Turkey and its neighbours and was taken over by the Soviets at the end of 1920.",
 description="After the Russian collapse Armenia declared independence on 28 May 1918, days after the battle of Sardarabad halted the Ottoman advance on Yerevan. The republic took in hundreds of thousands of refugees from the genocide of 1915. The Treaty of Sèvres (August 1920) promised a much larger Armenia with borders drawn by President Wilson, but Kemalist Turkey invaded that autumn and the Red Army entered Yerevan in December 1920.",
 conflicts="Armenia fought border wars with Georgia (1918) and Azerbaijan over Karabakh, Zangezur and Nakhichevan (1918–1920). The Turkish–Armenian war (September–December 1920) ended with the Treaty of Alexandropol.",
 leaders="Prime ministers Hovhannes Kajaznuni and Alexander Khatisian of the Dashnak party led the government; General Andranik Ozanian fought in Zangezur.",
 religion="The Armenian Apostolic Church, centred at Etchmiadzin, was the national church.",
 culture="Yerevan grew from a provincial town into a capital; Yerevan State University was founded in 1919.",
 literature="Hovhannes Tumanyan and Avetik Isahakyan were the leading writers of the period.",
 art="Martiros Saryan, whose bright landscapes shaped modern Armenian painting, designed the republic's coat of arms.",
 ideas="Armenian nationalism focused on the 'Wilsonian' borders and the recognition of the 1915 genocide.",
 science="The new university and the state's refugee relief, supported by Near East Relief, were the main institutions.",
 story=[{"title":"Sardarabad","text":"In May 1918 Armenian troops, militia and villagers stopped the Ottoman army at Sardarabad, west of Yerevan. Church bells rang across the region to call everyone to fight. Armenians still treat it as the battle that saved the nation."}],
 sources="Encyclopaedia Britannica, 'Armenia: The First Republic'; R. G. Hovannisian, The Republic of Armenia (4 vols, 1971–1996).",
 images=[("Sardarapat Memorial","Sardarapat memorial to the 1918 battle that preceded Armenian independence","culture")])

add(id="georgia-dr", name="Democratic Republic of Georgia", type="republic", yearsActive="1918–1921",
 summary="The independent Georgian republic led by Menshevik social democrats, recognised by the League's great powers in 1921 just weeks before the Red Army invaded.",
 description="Georgia declared independence on 26 May 1918 as the Transcaucasian Federation broke up, first under German protection and then British. Its Menshevik government carried out land reform, held free elections and drew visits from European socialists such as Karl Kautsky. Soviet Russia recognised it in May 1920, but in February 1921 the Red Army invaded and Tbilisi fell on 25 February.",
 conflicts="Georgia fought Armenia in December 1918 over Lori and faced risings in South Ossetia and Abkhazia. The Red Army invasion of February–March 1921 ended independence.",
 leaders="Noe Zhordania headed the government (1918–1921); Noe Ramishvili and Irakli Tsereteli were leading Mensheviks.",
 religion="The Georgian Orthodox Church restored its autocephaly in 1917.",
 culture="Tbilisi State University opened in 1918, the first university in the Caucasus.",
 literature="The Blue Horns symbolist poets, including Titsian Tabidze and Paolo Iashvili, made Tbilisi a literary hub.",
 art="Lado Gudiashvili and David Kakabadze painted in Tbilisi's café-and-cabaret milieu.",
 ideas="It was one of the few states run by democratic socialists, and its government in exile in Paris remained a symbol for European social democracy.",
 science="Ivane Javakhishvili founded Tbilisi State University.",
 story=[{"title":"Kautsky's visit","text":"In 1920 Karl Kautsky, Ramsay MacDonald and other socialist leaders visited Georgia and praised it as a model socialist democracy. Kautsky's book on Georgia appeared in 1921, just after the Red Army invaded."}],
 sources="Encyclopaedia Britannica, 'Georgia: Independence'; S. F. Jones, Socialism in Georgian Colors (2005).",
 images=[("Tbilisi State University","Tbilisi State University, founded in 1918","culture")])

add(id="azerbaijan-dr", name="Azerbaijan Democratic Republic", type="republic", yearsActive="1918–1920",
 summary="The first secular republic in the Muslim world, declared in 1918 and overthrown by the Red Army in April 1920 for the oil of Baku.",
 description="Azerbaijan declared independence on 28 May 1918 and moved its capital from Ganja to Baku once Ottoman troops took the city in September. Its parliament gave women the vote in 1919. In April 1920 the Red Army, invited by local Bolsheviks, occupied Baku and its oilfields and the republic became the Azerbaijan SSR.",
 conflicts="The 'March Days' of 1918 in Baku saw mass killings of Muslims; Ottoman and Azerbaijani forces then took the city in September 1918, with killings of Armenians. Armenia and Azerbaijan fought over Karabakh, Zangezur and Nakhichevan.",
 leaders="Mammad Amin Rasulzade of the Musavat party led the independence movement; Fatali Khan Khoyski and Nasib Yusifbeyli were prime ministers.",
 religion="The population was mostly Shia Muslim, but the republic was secular and its constitution guaranteed religious freedom.",
 culture="Baku State University was founded in 1919; Uzeyir Hajibeyov had already composed the first opera of the Muslim East, Leyli and Majnun (1908).",
 literature="Jalil Mammadguluzadeh's satirical magazine Molla Nasraddin was widely read across the Muslim world.",
 art="Theatre and opera flourished in oil-rich Baku.",
 ideas="Rasulzade combined Turkic nationalism, Islamic modernism and parliamentary democracy.",
 science="Baku's oil industry, then one of the largest in the world, was the main prize in the region.",
 story=[{"title":"Votes for women","text":"In 1919 Azerbaijan gave women the vote, before the United States, France or Italy. It was the first Muslim-majority country to do so."}],
 sources="Encyclopaedia Britannica, 'Azerbaijan: History'; T. Swietochowski, Russian Azerbaijan 1905–1920 (1985).",
 images=[("Mammad Amin Rasulzade","Mammad Amin Rasulzade, leader of the Azerbaijani independence movement","leader")])

add(id="cyprus", name="Republic of Cyprus", type="republic", yearsActive="1960–present",
 summary="The island republic that won independence from Britain in August 1960 under a power-sharing constitution between Greek and Turkish Cypriots.",
 description="Cyprus was ruled by Britain from 1878 and became a crown colony in 1925. From 1955 the Greek Cypriot EOKA guerrillas fought for union with Greece (enosis), while Turkish Cypriots wanted partition. The Zurich–London agreements made Cyprus independent on 16 August 1960, with a Greek Cypriot president, a Turkish Cypriot vice-president, guarantees from Britain, Greece and Turkey, and two British sovereign base areas. The settlement broke down in intercommunal violence in 1963–64.",
 conflicts="The EOKA campaign (1955–1959) ended with the independence agreements; fighting in December 1963 led to the UN peacekeeping force (1964) and, after a Greek-backed coup, the Turkish invasion of 1974.",
 leaders="Archbishop Makarios III was the first president, with Fazıl Küçük as vice-president; Georgios Grivas led EOKA.",
 religion="Greek Cypriots belong to the autocephalous Church of Cyprus, whose archbishop was also the community's political leader; Turkish Cypriots are Sunni Muslims.",
 culture="Greek and Turkish communities lived in mixed villages before 1963 but kept separate schools, churches and mosques.",
 literature="Lawrence Durrell's Bitter Lemons (1957) describes the island during the EOKA emergency.",
 art="Byzantine painted churches in the Troodos mountains, later a World Heritage Site, are the island's best-known art.",
 ideas="The 1960 constitution tried to share power by fixed ratios between communities, an early experiment in consociational democracy.",
 science="The economy rested on agriculture, copper mining and the British bases.",
 story=[{"title":"Guaranteed independence","text":"The Treaty of Guarantee gave Britain, Greece and Turkey the right to act to restore the 1960 settlement. Turkey invoked it in 1974, and the island has been divided ever since."}],
 sources="Encyclopaedia Britannica, 'Cyprus: History'; W. Mallinson, Cyprus: A Modern History (2005).",
 images=[("Makarios III 1962","Archbishop Makarios III, first president of Cyprus, on a visit to Italy in 1962","leader")])
